// Utforskingskode. Ett datasett, én felles fasemal og to presentasjoner. Ingen faktisk innlogging eller lagring.
const $=id=>document.getElementById(id), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const D=s=>new Date(s+'T12:00:00Z'), iso=d=>d.toISOString().slice(0,10), plus=(d,n)=>new Date(d.getTime()+n*86400000), startWeek=d=>plus(d,-((d.getUTCDay()+6)%7));
const TODAY='2026-10-27', F=(d,opt)=>new Intl.DateTimeFormat('nb-NO',{timeZone:'UTC',...opt}).format(typeof d==='string'?D(d):d), cap=s=>s[0].toUpperCase()+s.slice(1);
const MONTHS=['Januar','Februar','Mars','April','Mai','Juni','Juli','August','September','Oktober','November','Desember'];
let isAdmin=true, area='budget', section='queue', focusYear=2026, calendarAnchor=TODAY, calendarMode='month', calendarYears=[2026,2027,2028], budgetMode='timeline', activeId=null, editId=null;
let phases=[{name:'Forberedelser',start:-15},{name:'Utarbeidelse av budsjettforslag',start:-10},{name:'Fremleggelse og vedtak',start:-3},{name:'Gjennomføring og revidering',start:0},{name:'Regnskap',start:12}],phaseEnd=16;
const sampleStages=[['Arbeidet starter',-15],['Innspill til budsjettarbeidet',-12],['Marskonferanse',-10],['Augustkonferanse',-5],['Budsjettet legges frem',-3],['Revidert budsjett',3],['Nysaldering',10],['Regnskap',15]];
function relDate(year,offset,day=1){return iso(new Date(Date.UTC(year,offset,day,12)))}
function relMonth(date,year){const d=D(date);return (d.getUTCFullYear()-year)*12+d.getUTCMonth()}
let records=[2026,2027,2028].flatMap(year=>sampleStages.map(([title,offset],i)=>({id:year+'-'+i,title,date:relDate(year,offset),budgetYear:year,precision:'month',category:i===7?'Regnskap':'Budsjett',note:'Konstruert eksempel på en milepæl i budsjettløpet. Måneden illustrerer prosessen; en fast dagsdato er ikke satt.',visibility:['FA'],published:true})));
records.push({id:'oppfolging-2026',title:'Oppfølging før nysalderingen',date:TODAY,budgetYear:2026,precision:'day',category:'Budsjett',note:'Konstruert frist for å vise samme opplysning i kalender og budsjettår.',visibility:['FA'],published:true});
records.push({id:'gul-2027',title:'Avklaringer til Gul bok',date:'2026-10-28',budgetYear:2027,precision:'day',category:'Gul bok',note:'Konstruert fristdato. Den offentlige lenken nedenfor illustrerer kildeplasseringen, og er ikke bevis for datoen i eksempelet.',visibility:['FA','FIN-FAG'],published:true,sourceUrl:'https://www.regjeringen.no/globalassets/departementene/fin/rundskriv/arlige/2026/r-7-2026.pdf',sourceName:'R-7/2026'});
let proposals=[{id:'p1',type:'Ny frist',sender:'Eksempel på bidragsyter i FA',title:'Supplerende opplysninger til nysalderingen',date:'2026-10-30',budgetYear:2026,precision:'day',category:'Budsjett',note:'Eksempelforslag som kan godkjennes og deretter vises i begge visninger.',visibility:['FA']},{id:'p2',type:'Endring',sender:'Eksempel på bidragsyter i FIN',target:'gul-2027',title:'Avklaringer til Gul bok',date:'2026-10-29',budgetYear:2027,precision:'day',category:'Gul bok',note:'Eksempel på foreslått flytting av dato. Synligheten beholdes.'}];
function color(year){return year===2026?'#66518c':year===2027?'#3448a1':'#1a655b'}
function fullDate(record){return record.precision==='month'?cap(F(record.date,{month:'long',year:'numeric'}))+' · tentativ':F(record.date,{day:'numeric',month:'long',year:'numeric'})}
function relativeText(offset){const month=((offset%12)+12)%12,yr=Math.floor(offset/12);return MONTHS[month].toLowerCase()+' '+(yr===0?'t':yr<0?'t−'+(-yr):'t+'+yr)}
function phaseFor(record){const offset=relMonth(record.date,record.budgetYear);return phases.find((p,i)=>offset>=p.start&&offset<(phases[i+1]?.start??phaseEnd))?.name??'Utenfor faseinndelingen'}
function visible(){return records.filter(r=>r.published&&(isAdmin||r.visibility.includes('FA')))}
function budgetRecords(){return visible().filter(r=>r.budgetYear===focusYear).sort((a,b)=>a.date.localeCompare(b.date))}
function calendarRecords(){const month=calendarAnchor.slice(0,7);return visible().filter(r=>calendarYears.includes(r.budgetYear)&&r.date.slice(0,7)===month).sort((a,b)=>a.date.localeCompare(b.date))}
function notify(text){$('feedback').textContent=text;$('feedback').hidden=false}
function navigation(){const items=[['calendar','Kalender'],['budget','Budsjettår'],['aarshjul','Årshjul'],...(isAdmin?[['admin','Administrasjon']]:[])];$('navigation').innerHTML=items.map(([key,name])=>`<button type="button" data-area="${key}" class="${area===key?'active':''}" ${area===key?'aria-current="page"':''}>${name}${key==='admin'&&proposals.length?' · '+proposals.length:''}</button>`).join('');$('roleLabel').textContent=isAdmin?'Administrator':'Leser · FA';$('roleToggle').textContent=isAdmin?'Se som leser':'Tilbake til administrator'}
function sidebar(){let h='';if(area==='admin'){h='<p class="eyebrow">Forvaltning</p><h2>Administrasjon</h2>';const entries=[['queue','Godkjenningskø'],['register','Fristregister'],['phases','Felles fasemal'],['documents','Dokumenter og årsmal'],['groups','Grupper og innsyn'],['sharing','Eksport og deling'],['internal','Internkalender']];h+=entries.map(([key,title])=>`<button type="button" class="side-button ${section===key?'active':''}" data-section="${key}">${title}${key==='queue'?'<span class="side-count">'+proposals.length+'</span>':''}</button>`).join('')}else if(area==='calendar'){h='<p class="eyebrow">Din kalender</p><h2>Vis budsjettår</h2>';h+=[2026,2027,2028].map(year=>`<label class="side-check"><input type="checkbox" name="calendarYear" value="${year}" ${calendarYears.includes(year)?'checked':''}><i class="dot y${year}"></i>${year}</label>`).join('');h+='<div class="aside-note"><strong>Samme frister, ulike perspektiver</strong>Kalender viser datoene på tvers av valgte budsjettår. Budsjettår samler ett helt løp.</div>'}else{h='<p class="eyebrow">Hele budsjettløpet</p><h2>Velg budsjettår</h2>';h+=[2026,2027,2028].map(year=>`<label class="year-option"><input type="radio" name="focusYear" value="${year}" ${focusYear===year?'checked':''}>${year}<i class="dot y${year}"></i></label>`).join('');h+='<div class="aside-note"><strong>Samme frister, ulike perspektiver</strong>En frist som oppdateres, får samme opplysninger i Kalender, Budsjettår og Fristregister.</div>';if(isAdmin)h+='<div class="aside-note"><strong>Faser for alle budsjettår</strong>Én felles mal styrer navn og månedsgrenser.<br><button type="button" class="side-button" data-action="phases">Rediger fasemal →</button></div>'}$('sidebar').innerHTML=h}
function header(title,description,actions=''){return `<div class="heading"><div><p class="eyebrow">${area==='admin'?'Administrasjon':area==='calendar'?'Kalender':'Budsjettår'}</p><h1>${title}</h1><p class="lead">${description}</p></div>${actions?'<div class="heading-actions">'+actions+'</div>':''}</div>`}
function adminActions(withPhases=false){return isAdmin?`${withPhases?'<button type="button" class="small-button" data-action="phases">Rediger faser</button>':''}<button type="button" class="primary" data-action="new">+ Ny frist</button>`:''}
function mobileYear(){return `<div class="mobile-budget"><label for="mobileYear">Budsjettår</label><select class="small-select" id="mobileYear">${[2026,2027,2028].map(y=>`<option ${y===focusYear?'selected':''}>${y}</option>`).join('')}</select></div>`}
function budgetView(){const items=budgetRecords();if(!items.some(e=>e.id===activeId))activeId=items[4]?.id??items[0]?.id??null;document.documentElement.style.setProperty('--year',color(focusYear));const first=Math.min(phases[0].start,...items.map(r=>relMonth(r.date,focusYear))),end=Math.max(phaseEnd,...items.map(r=>relMonth(r.date,focusYear)+1));return header('Budsjettåret '+focusYear,'Forberedelser, fremleggelse, gjennomføring og regnskap i samme løp.',adminActions(true))+mobileYear()+`<div class="toolbar"><div class="range">${cap(F(relDate(focusYear,first),{month:'long',year:'numeric'}))} – ${F(relDate(focusYear,end-1),{month:'long',year:'numeric'})}</div><div class="segmented" role="group" aria-label="Vis budsjettåret som"><button type="button" data-budget-mode="timeline" aria-pressed="${budgetMode==='timeline'}">Tidslinje</button><button type="button" data-budget-mode="list" aria-pressed="${budgetMode==='list'}">Fristliste</button></div></div><section class="canvas"><div class="chart-scroll" tabindex="0" aria-label="Budsjettårets tidslinje, kan rulles vannrett">${budgetMode==='timeline'?timeline(items,first,end):listMarkup(items)}</div><div class="chart-footer"><span>${items.length} publiserte frister · hele budsjettløpet vises</span><span class="today-text">I dag · 27. oktober 2026</span></div></section>${activeId?selectedDetail(activeId):''}<p class="data-relation">Kalender, Budsjettår og Fristregister viser de samme fristene. Fasene er en visuell inndeling og endrer ingen fristdatoer.</p>`}
function timeline(items,first,end){const span=end-first,minWidth=Math.max(980,Math.ceil(items.length/2)*178+48);let h=`<div class="chart" style="min-width:${minWidth}px"><div class="years" style="grid-template-columns:`;let bands=[];for(let offset=first;offset<end;){const y=focusYear+Math.floor(offset/12),next=Math.min(end,(Math.floor(offset/12)+1)*12);bands.push({year:y,count:next-offset});offset=next}h+=bands.map(b=>b.count+'fr').join(' ')+`">`+bands.map(b=>`<div class="year-band">${b.year}<small>${b.year-focusYear===0?'t':b.year<focusYear?'t−'+(focusYear-b.year):'t+'+(b.year-focusYear)} · ${b.year===focusYear?'Budsjettåret':b.year<focusYear?'Forberedelse og forslag':'Regnskap'}</small></div>`).join('')+'</div><div class="plot" id="plot"><div class="axis"></div>';for(let offset=first;offset<end;offset++){const x=(offset-first+.5)/span*100,d=D(relDate(focusYear,offset));h+=`<span class="tick" style="left:${x}%"></span>`;if(offset===first||offset===end-1||d.getUTCMonth()%3===0)h+=`<span class="month-label" style="left:${x}%">${F(d,{month:'short'})}</span>`}items.forEach((e,i)=>{const d=D(e.date),fraction=e.precision==='month'?.5:(d.getUTCDate()-1)/new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+1,0)).getUTCDate(),x=(relMonth(e.date,focusYear)-first+fraction)/span*100;h+=`<div class="station ${i%2?'bottom':'top'}" data-position="${x}" style="left:${x}%"><span class="stem"></span><span class="node"></span><button type="button" class="station-card" data-select-event="${e.id}" aria-pressed="${activeId===e.id}"><small>${esc(fullDate(e))}</small><strong>${esc(e.title)}</strong><span class="relative">${esc(phaseFor(e))}</span></button></div>`});const today=D(TODAY),pos=(relMonth(TODAY,focusYear)-first+(today.getUTCDate()-1)/31)/span*100;if(pos>=0&&pos<=100)h+=`<div class="now" style="left:${pos}%"><span>I dag · 27. okt. 2026</span></div>`;h+='</div><div class="phase-row" style="min-width:0;margin:0 -24px">';if(first<phases[0].start)h+=`<div class="phase-cell" style="flex:${phases[0].start-first}"><small>Utenfor fasemalen</small></div>`;phases.forEach((p,i)=>{const pEnd=phases[i+1]?.start??phaseEnd,tag=isAdmin?'button':'div';h+=`<${tag} ${isAdmin?'type="button" data-action="phases"':''} class="phase-cell" style="flex:${pEnd-p.start}"><strong>${esc(p.name)}</strong><small>${relativeText(p.start)} – ${relativeText(pEnd-1)}</small>${isAdmin?'<span class="edit-hint">Rediger fase ↗</span>':''}</${tag}>`});if(end>phaseEnd)h+=`<div class="phase-cell" style="flex:${end-phaseEnd}"><small>Utenfor fasemalen</small></div>`;return h+'</div></div>'}
function listMarkup(items){return '<div class="list-lines">'+(items.length?items.map(e=>`<div class="frist-row"><span class="date-cell">${esc(fullDate(e))}</span><button type="button" class="title-button" data-detail-event="${e.id}">${esc(e.title)}</button><span class="year-pill y${e.budgetYear}">${e.budgetYear}</span><span class="row-actions">${isAdmin?`<button type="button" class="small-button" data-edit-event="${e.id}">Rediger</button>`:''}</span></div>`).join(''):'<div class="empty">Ingen frister i utvalget.</div>')+'</div>'}
function selectedDetail(id){const e=records.find(r=>r.id===id);if(!e)return '';return `<section class="detail"><div><p class="eyebrow">Valgt frist · ${esc(phaseFor(e))}</p><h2>${esc(e.title)}</h2><p>${esc(e.note)}</p>${e.sourceUrl?`<div class="source-section"><h3>Kilderundskriv</h3><a href="${esc(e.sourceUrl)}" target="_blank" rel="noopener noreferrer" referrerpolicy="no-referrer">${esc(e.sourceName)} · Les rundskrivet på regjeringen.no ↗</a><p class="hint">Eksempelkobling. Fristdatoen er konstruert.</p></div>`:''}</div><div class="detail-meta"><span>Budsjettår ${e.budgetYear}</span><strong>${esc(fullDate(e))}</strong>${isAdmin?`<span>Synlig for ${e.visibility.join(', ')}</span><button type="button" class="primary small-button" data-edit-event="${e.id}">Rediger frist</button>`:''}<button type="button" class="small-button" data-calendar-event="${e.id}">Vis i kalenderen →</button></div></section>`}
function isoWeek(d){const t=new Date(d);t.setUTCDate(t.getUTCDate()+3-((t.getUTCDay()+6)%7));const first=new Date(Date.UTC(t.getUTCFullYear(),0,4,12));return 1+Math.round((t-startWeek(first))/604800000)}
function calendarView(){const items=calendarRecords(),d=D(calendarAnchor);let h=header('Frister','Se fristene i kalenderen, og behold oversikten over budsjettårene.',adminActions());h+=`<div class="mobile-budget">${[2026,2027,2028].map(y=>`<label class="side-check"><input type="checkbox" name="calendarYear" value="${y}" ${calendarYears.includes(y)?'checked':''}>${y}</label>`).join('')}</div><div class="calendar-toolbar"><div class="calendar-period"><button type="button" data-action="today">I dag</button><button type="button" class="arrow" data-move="-1" aria-label="Forrige måned">‹</button><button type="button" class="arrow" data-move="1" aria-label="Neste måned">›</button><h2>${cap(F(d,{month:'long',year:'numeric'}))}</h2></div><div class="segmented" role="group" aria-label="Kalendervisning"><button type="button" data-calendar-mode="month" aria-pressed="${calendarMode==='month'}">Måned</button><button type="button" data-calendar-mode="list" aria-pressed="${calendarMode==='list'}">Liste</button></div></div><div class="calendar-legend">${calendarYears.map(y=>`<span><i class="dot y${y}"></i>Budsjettår ${y}</span>`).join('')}</div>`;const tentative=items.filter(e=>e.precision==='month');if(tentative.length)h+='<div class="tentatives"><strong>Dato ikke fastsatt</strong>'+tentative.map(e=>`<button type="button" data-detail-event="${e.id}">${esc(e.title)} · ${e.budgetYear}</button>`).join('')+'</div>';h+='<section class="canvas">';if(calendarMode==='list')h+=listMarkup(items);else{const first=new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth(),1,12)),last=new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+1,0,12)),start=startWeek(first),weeks=Math.ceil(((last-start)/86400000+1)/7);h+='<div class="month-scroll" tabindex="0" aria-label="Månedskalender, kan rulles vannrett"><table class="month-table"><caption class="sr">Frister i '+esc(cap(F(d,{month:'long',year:'numeric'})))+'</caption><thead><tr><th scope="col">Uke</th>'+['Man','Tir','Ons','Tor','Fre','Lør','Søn'].map(s=>'<th scope="col">'+s+'</th>').join('')+'</tr></thead><tbody>';for(let w=0;w<weeks;w++){h+='<tr><th scope="row">'+isoWeek(plus(start,w*7))+'</th>';for(let i=0;i<7;i++){const day=plus(start,w*7+i),date=iso(day),outside=day.getUTCMonth()!==d.getUTCMonth(),es=outside?[]:items.filter(e=>e.precision==='day'&&e.date===date);h+=`<td class="${i>4?'weekend ':''}${outside?'outside ':''}${date===TODAY?'today':''}"><button type="button" class="day-number" data-day="${date}" aria-label="${isAdmin?'Opprett frist':'Vis dato'} ${esc(F(day,{day:'numeric',month:'long',year:'numeric'}))}">${day.getUTCDate()}</button>${es.slice(0,3).map(e=>`<button type="button" class="cal-event y${e.budgetYear}" data-detail-event="${e.id}" title="${esc(e.title)}">${esc(e.title)}</button>`).join('')}${es.length>3?`<button type="button" class="small-button" data-day="${date}">+ ${es.length-3} flere</button>`:''}</td>`}h+='</tr>'}h+='</tbody></table></div>'}return h+`<div class="chart-footer"><span>${items.length} frister i måneden · ${items.filter(e=>e.precision==='day').length} med fast dag</span><span>Samme opplysninger i Budsjettår</span></div></section><p class="data-relation">Dette administratorutkastet viser måned og liste. Den tidligere ukevisningen og alle eksisterende funksjoner videreføres i løsningen.</p>`}
function queueView(){return header('Godkjenningskø','Kontroller innhold og synlighet før et forslag blir publisert.')+`<div class="queue-list">${proposals.length?proposals.map(p=>{const original=p.target?records.find(r=>r.id===p.target):null;return `<article class="queue-card"><div class="queue-top"><div><p class="eyebrow">${esc(p.sender)}</p><h2>${esc(p.title)}</h2><p>Budsjettår ${p.budgetYear} · ${esc(p.category)}</p></div><span class="queue-kind">${p.type}</span></div><div class="queue-values"><div><small>${original?'Gjeldende dato':'Foreslått dato'}</small><strong>${esc(fullDate(original??p))}</strong></div><div><small>${original?'Ny dato':'Når forslaget godkjennes'}</small><strong>${original?esc(fullDate(p)):'Vises i Kalender og Budsjettår'}</strong></div></div><p class="hint">${esc(p.note)}</p><div class="queue-footer">${original?`<p class="hint">Synligheten beholdes: ${original.visibility.join(', ')}</p>`:`<div class="checkboxes" aria-label="Velg synlighet">${['FA','FAG','POL'].map(g=>`<label><input type="checkbox" data-proposal-group="${p.id}" value="${g}" ${g==='FA'?'checked':''}>${g}${g==='POL'?' – aktivt valg':''}</label>`).join('')}</div>`}<div class="queue-buttons"><button type="button" class="primary small-button" data-approve="${p.id}">Godkjenn og publiser</button><button type="button" class="small-button" data-reject="${p.id}">Avvis</button></div></div></article>`}).join(''):'<div class="placeholder"><h2>Ingen forslag til behandling</h2><p>Godkjente forslag er tilgjengelige i de ordinære visningene.</p></div>'}</div>`}
function phasesView(){return header('Felles fasemal','Samme navn og månedsgrenser brukes for alle budsjettår.',isAdmin?'<button type="button" class="primary" data-action="phases">Rediger fasemal</button>':'')+'<section class="canvas"><div class="phase-summary">'+phases.map((p,i)=>`<div class="phase-summary-row"><div><strong>${esc(p.name)}</strong><small>Fra 1. ${relativeText(p.start)} til og med ${relativeText((phases[i+1]?.start??phaseEnd)-1)}</small></div><div><span class="year-pill">Alle budsjettår</span></div></div>`).join('')+'</div></section><p class="data-relation">Endringer gjelder inndelingen i leserens og administratorens tidslinje. De flytter ingen frister, endrer ikke synlighet og publiserer ingen nye hendelser.</p>'}
function adminView(){if(section==='queue')return queueView();if(section==='register')return header('Fristregister','Forvalt de samme publiserte fristene som vises i kalenderen og budsjettløpene.',adminActions())+'<section class="canvas">'+listMarkup(visible().sort((a,b)=>a.date.localeCompare(b.date)))+'</section>';if(section==='phases')return phasesView();const descriptions={documents:['Dokumenter og årsmal','Dagens dokumentopplasting, årsmaler og generering beholdes. Disse sidene skal bruke de samme feltene, knappene og tilbakemeldingene som resten av Atelier.'],groups:['Grupper og innsyn','Dagens gruppeforvaltning og innsyn beholdes med eksisterende policyer. Synlighetsgrupper og funksjonsroller er fortsatt forskjellige begreper.'],sharing:['Eksport og deling','Dagens Word-, JSON- og ICS-eksport og kalenderabonnement beholdes. Delingsregler og tokenvern endres ikke av utformingen.'],internal:['Internkalender','SBRs internrunder og gjøremål beholder sin egen arbeidsflate. De blandes ikke med de publiserte budsjettfristene.']};const [title,description]=descriptions[section];return header(title,'Eksisterende funksjon i samme Atelier-utforming.')+`<div class="placeholder"><h2>${title}</h2><p>${description}</p><p class="hint">Denne delen viser plasseringen i administratorløsningen. Selve funksjonen er ikke bygget på nytt i skissen.</p></div>`}
function render(){if(!isAdmin&&area==='admin')area='budget';navigation();sidebar();$('content').innerHTML=area==='budget'?budgetView():area==='calendar'?calendarView():area==='aarshjul'?header('Årshjul','Dagens oversikt per budsjettår beholdes.',adminActions())+'<section class="canvas">'+listMarkup(budgetRecords())+'</section>':adminView();positionCards()}
function positionCards(){const plot=$('plot');if(!plot)return;const width=plot.clientWidth,stations=[...plot.querySelectorAll('.station')];for(const parity of [0,1]){const row=stations.map((station,i)=>({station,i,x:Number(station.dataset.position)/100*width})).filter(n=>n.i%2===parity);row.forEach((n,i)=>{n.left=Math.max(0,Math.min(width-166,n.x-83));if(i)n.left=Math.max(n.left,row[i-1].left+178)});if(row.length&&row.at(-1).left>width-166){row.at(-1).left=width-166;for(let i=row.length-2;i>=0;i--)row[i].left=Math.min(row[i].left,row[i+1].left-178)}row.forEach(n=>n.station.querySelector('.station-card').style.left=(n.left-n.x)+'px')}}
function openEvent(id=null,date=null){if(!isAdmin)return;editId=id;const e=id?records.find(r=>r.id===id):{title:'',date:date??calendarAnchor,budgetYear:focusYear,precision:'day',category:'Budsjett',note:'',visibility:[]};$('eventTitle').textContent=id?'Rediger frist':'Ny frist';$('eventName').value=e.title;$('eventDate').type=e.precision==='month'?'month':'date';$('eventDate').value=e.precision==='month'?e.date.slice(0,7):e.date;$('eventYear').value=e.budgetYear;$('eventPrecision').value=e.precision;$('eventCategory').value=e.category;$('eventNote').value=e.note;document.querySelectorAll('input[name=visibility]').forEach(n=>n.checked=e.visibility.includes(n.value));$('eventError').hidden=true;$('precisionHint').textContent=e.precision==='month'?'Måneden er tentativ. Det vises ingen fast dagsdato.':'Datoen gjelder fristen. Budsjettåret kan være et annet år.';if($('detailDialog').open)$('detailDialog').close();$('eventDialog').showModal()}
function openDetail(id){const e=records.find(r=>r.id===id);if(!e)return;activeId=id;$('detailTitle').textContent=e.title;$('detailContent').innerHTML=`<p class="detail-date">${esc(fullDate(e))}</p><div class="detail-facts"><div><small>Budsjettår</small>${e.budgetYear}</div><div><small>Kategori</small>${esc(e.category)}</div></div>${e.sourceUrl?`<section class="source-section"><h3>Kilderundskriv</h3><a href="${esc(e.sourceUrl)}" target="_blank" rel="noopener noreferrer" referrerpolicy="no-referrer">${esc(e.sourceName)} · Les rundskrivet på regjeringen.no ↗</a><p class="hint">Eksempelkobling. Datoen er konstruert; lenken åpnes i ny fane.</p></section>`:''}<h3>Om fristen</h3><p>${esc(e.note)}</p>${isAdmin?'<p class="hint">Synlig for '+e.visibility.join(', ')+'</p>':''}`;$('detailActions').innerHTML=`<button type="button" data-budget-event="${e.id}">Vis i Budsjettår</button>${isAdmin?`<button type="button" class="primary" data-edit-event="${e.id}">Rediger frist</button>`:''}`;$('detailDialog').showModal()}
function relativeFields(prefix,value){const month=((value%12)+12)%12,year=Math.floor(value/12);return `<div class="relative-fields"><select aria-label="Måned ${prefix}" name="${prefix}Month">${MONTHS.map((m,i)=>`<option value="${i}" ${i===month?'selected':''}>${m}</option>`).join('')}</select><select aria-label="År ${prefix}" name="${prefix}Year">${[-2,-1,0,1].map(y=>`<option value="${y}" ${y===year?'selected':''}>${y===0?'Budsjettåret (t)':y<0?(-y)+' år før (t−'+(-y)+')':'Året etter (t+1)'}</option>`).join('')}</select></div>`}
function openPhases(){if(!isAdmin)return;$('phaseFields').innerHTML=phases.map((p,i)=>`<div class="phase-editor-row"><label>Fase ${i+1}<input name="phaseName${i}" value="${esc(p.name)}" maxlength="100" required><small>Navnet vises likt for alle roller og budsjettår.</small></label><div><label>Starter 1.</label>${relativeFields('phase'+i,p.start)}<small>Varer frem til neste fase starter.</small></div></div>`).join('');$('phaseEndFields').innerHTML=relativeFields('end',phaseEnd-1);$('phaseError').hidden=true;$('phasePreview').textContent='Felles standard: '+phases.map(p=>p.name).join(' → ');$('phaseDialog').showModal()}
function showCalendar(id){const e=records.find(r=>r.id===id);calendarAnchor=e.date;if(!calendarYears.includes(e.budgetYear))calendarYears.push(e.budgetYear);area='calendar';if($('detailDialog').open)$('detailDialog').close();render()}
function showBudget(id){const e=records.find(r=>r.id===id);focusYear=e.budgetYear;activeId=id;area='budget';if($('detailDialog').open)$('detailDialog').close();render()}
function approve(id){if(!isAdmin)return;const p=proposals.find(p=>p.id===id);if(!p)return;let groups;if(p.target){groups=records.find(r=>r.id===p.target).visibility}else groups=[...document.querySelectorAll(`[data-proposal-group="${id}"]:checked`)].map(n=>n.value);if(!groups.length){notify('Velg hvem fristen skal være synlig for før godkjenning.');return}if(p.target){const target=records.find(r=>r.id===p.target);Object.assign(target,{title:p.title,date:p.date,budgetYear:p.budgetYear,precision:p.precision,category:p.category,note:p.note})}else records.push({...p,id:'published-'+p.id,visibility:groups,published:true});proposals=proposals.filter(p=>p.id!==id);render();notify('Forslaget er godkjent og publisert. Den samme fristen er nå tilgjengelig i Kalender og Budsjettår.')}
$('eventForm').addEventListener('submit',e=>{e.preventDefault();if(!isAdmin)return;const groups=[...document.querySelectorAll('input[name=visibility]:checked')].map(n=>n.value),rawDate=$('eventDate').value,title=$('eventName').value.trim();if(!title||!rawDate||!groups.length){$('eventError').textContent='Fyll inn tittel og dato, og velg minst én synlighetsgruppe.';$('eventError').hidden=false;$('eventName').focus();return}const data={title,date:$('eventPrecision').value==='month'?rawDate+'-01':rawDate,budgetYear:Number($('eventYear').value),precision:$('eventPrecision').value,category:$('eventCategory').value,note:$('eventNote').value.trim(),visibility:groups,published:true};if(editId){Object.assign(records.find(r=>r.id===editId),data);activeId=editId}else{const id='manual-'+Date.now();records.push({...data,id});activeId=id}focusYear=data.budgetYear;calendarAnchor=data.date;if(!calendarYears.includes(data.budgetYear))calendarYears.push(data.budgetYear);$('eventDialog').close();render();notify('Fristen er lagret og publisert. Kalender og Budsjettår viser samme oppdaterte frist.')});
$('eventPrecision').addEventListener('change',()=>{const input=$('eventDate');if($('eventPrecision').value==='month'){const value=input.value.slice(0,7);input.type='month';input.value=value;$('precisionHint').textContent='Du registrerer en tentativ måned. Det vises ingen fast dagsdato.'}else{const value=input.value;input.type='date';input.value=value.length===7?value+'-01':value;$('precisionHint').textContent='Datoen kan redigeres før publisering.'}});
$('phaseForm').addEventListener('submit',e=>{e.preventDefault();if(!isAdmin)return;const f=new FormData(e.target),next=phases.map((_,i)=>({name:String(f.get('phaseName'+i)).trim(),start:Number(f.get('phase'+i+'Year'))*12+Number(f.get('phase'+i+'Month'))})),end=Number(f.get('endYear'))*12+Number(f.get('endMonth'))+1;if(next.some(p=>!p.name)||next.some((p,i)=>i>0&&p.start<=next[i-1].start)||end<=next.at(-1).start){$('phaseError').textContent='Gi alle fasene navn og velg startmåneder i stigende rekkefølge. Sluttgrensen må være etter siste fase.';$('phaseError').hidden=false;return}phases=next;phaseEnd=end;$('phaseDialog').close();render();notify('Felles fasemal er oppdatert for alle budsjettår og begge roller. Ingen fristdatoer er endret.')});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.close)$(b.dataset.close).close();if(b.dataset.area){$('feedback').hidden=true;area=b.dataset.area;render()}if(b.dataset.section){$('feedback').hidden=true;area='admin';section=b.dataset.section;render()}if(b.dataset.budgetMode){budgetMode=b.dataset.budgetMode;render()}if(b.dataset.calendarMode){calendarMode=b.dataset.calendarMode;render()}if(b.dataset.selectEvent){activeId=b.dataset.selectEvent;render()}if(b.dataset.detailEvent)openDetail(b.dataset.detailEvent);if(b.dataset.editEvent)openEvent(b.dataset.editEvent);if(b.dataset.calendarEvent)showCalendar(b.dataset.calendarEvent);if(b.dataset.budgetEvent)showBudget(b.dataset.budgetEvent);if(b.dataset.action==='new')openEvent();if(b.dataset.action==='phases')openPhases();if(b.dataset.action==='today'){calendarAnchor=TODAY;render()}if(b.dataset.move){const d=D(calendarAnchor);calendarAnchor=iso(new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+Number(b.dataset.move),1,12)));render()}if(b.dataset.day){if(isAdmin)openEvent(null,b.dataset.day);else{const items=visible().filter(r=>r.date===b.dataset.day&&r.precision==='day'&&calendarYears.includes(r.budgetYear));if(items.length)openDetail(items[0].id);else notify('Ingen datofestede frister denne dagen med ditt utvalg.')}}if(b.dataset.approve)approve(b.dataset.approve);if(b.dataset.reject&&isAdmin){proposals=proposals.filter(p=>p.id!==b.dataset.reject);render();notify('Forslaget er avvist. De publiserte fristene er uendret.')}});
document.addEventListener('change',e=>{if(e.target.name==='focusYear'||e.target.id==='mobileYear'){focusYear=Number(e.target.value);render()}if(e.target.name==='calendarYear'){const y=Number(e.target.value);calendarYears=e.target.checked?[...new Set([...calendarYears,y])]:calendarYears.filter(n=>n!==y);render()}});
$('roleToggle').onclick=()=>{isAdmin=!isAdmin;render()};new ResizeObserver(positionCards).observe($('content'));render();
